// Agente de Infraestrutura - Inicialização
// Especialista em: Linux, Containers Docker, Rede, Traefik

const payload = $input.item.json.body || $input.item.json;

return [{
  json: {
    agent: {
      name: 'Agente de Infraestrutura',
      version: '1.0',
      specialization: ['Linux', 'Docker Containers', 'Rede', 'Traefik', 'Recursos do Sistema'],
      role: 'Diagnóstico e resolução de problemas de infraestrutura'
    },
    sessionId: payload.sessionId,
    timestamp: payload.timestamp,
    issues: payload.issues || [],
    context: payload.context || {},
    orchestratorDecision: payload.orchestratorDecision || {},
    status: 'analyzing'
  }
}];

// Agregar dados coletados para análise
const agentData = $('Inicializar Agente').item.json;
const apiHealth = $('Verificar Saúde API').item.json;
const metrics = $('Verificar Métricas Detalhadas').item.json;
const dbPerf = $('Verificar Performance DB').item.json[0] || {};

const collectedData = {
  api: {
    status: apiHealth.statusCode,
    response: apiHealth.body || {}
  },
  metrics: {
    available: metrics.statusCode === 200,
    data: metrics.body || ''
  },
  database: {
    connections: dbPerf,
    hasSlowQueries: parseFloat(dbPerf.longest_query_seconds || 0) > 5
  }
};

return [{
  json: {
    ...agentData,
    collectedData: collectedData,
    readyForAnalysis: true
  }
}];

// Preparar prompt para Claude AI
const data = $input.item.json;
const promptTemplate = $env.PROMPT_INFRA_SPECIALIST || '';

// Substituir placeholders no prompt
let prompt = promptTemplate
  .replace(/\{\{issues\}\}/g, JSON.stringify(data.issues, null, 2))
  .replace(/\{\{context\}\}/g, JSON.stringify({
    ...data.context,
    collectedData: data.collectedData
  }, null, 2));

// Adicionar contexto do agente
prompt = `Você é o Agente de Infraestrutura do CredGestor.\n\n` + prompt;

return [{
  json: {
    ...data,
    prompt: prompt,
    model: $env.LLM_MODEL || 'claude-3-5-sonnet-20241022'
  }
}];

